async function loadTemplates(){const user=window.ForgeCloud?.partyConnection()?.user,client=window.ForgeVTTCloud?.client();if(user&&!user.is_anonymous&&client){const {data,error}=await client.from('forge_vtt_token_templates').select('id,name,data').eq('owner_id',user.id).order('updated_at',{ascending:false});if(!error){templates=data.map(x=>({...x.data,_templateId:x.id}));return}}try{templates=JSON.parse(localStorage.getItem('forge-vtt-templates:'+(user?.id||'guest'))||'[]')}catch{templates=[]}}
