function damage(tokens){const d=modal('Damage or healing','<form data-damage><label>Amount<input type="number" name="amount" min="0" max="100000" value="1" required></label><label>Action<select name="action"><option value="damage">Damage</option><option value="healing">Healing</option></select></label><label class="vtt-check"><input type="checkbox" name="half"> Halve damage for resistance</label><button class="btn primary" type="submit">Apply</button></form>');d.querySelector('form').onsubmit=e=>{e.preventDefault();const amount=Number(d.querySelector('[name=amount]').value),heal=d.querySelector('[name=action]').value==='healing',half=d.querySelector('[name=half]').checked;edit(()=>tokens.forEach(t=>{if(t.hp===null)return;let n=half&&!heal?Math.floor(amount/2):amount;const temp=t.details?.tempHp||0;if(!heal){t.details={...t.details,tempHp:Math.max(0,temp-n)};n=Math.max(0,n-temp)}t.hp=Math.max(0,Math.min(t.maxHp,t.hp+(heal?n:-n)))}));d.close()}}
