if(q.tool==='draw'||q.tool==='ruler'){const opts=document.createElement('div');opts.className='vtt-draw-options';opts.innerHTML=`<label>${q.tool==='draw'?'Drawing':'Area'}<select data-shape>${(q.tool==='draw'?['pen','line','rect','ellipse','polygon','text','arrow','erase']:['ruler','cone','circle','square','beam']).map(v=>`<option ${v===(q.tool==='draw'?shape:measureShape)?'selected':''}>${v}</option>`).join('')}</select></label><label>Color<input type="color" data-stroke value="${stroke}"></label>${q.tool==='draw'?`<label>Fill<select data-fill><option value="none" ${fill==='none'?'selected':''}>None</option><option value="color" ${fill!=='none'?'selected':''}>Use color</option></select></label><label>Width<input type="number" min="1" max="30" data-thick value="${thickness}"></label><label>Opacity<input type="number" min="0" max="1" step=".1" data-opacity value="${opacity}"></label>${q.dm?'<label><input type="checkbox" data-hidden '+(hiddenDrawing?'checked':'')+'> GM only</label>':''}<button class="btn ghost" data-clear-own>Clear my drawings</button>${q.dm?'<button class="btn ghost" data-clear-all>Clear drawings</button>':''}`:`<label>Beam width (${h(settings(scene).units)})<input type="number" min="1" max="1000" data-beam value="${beamWidth}"></label>${allowedDraw()?'<label><input type="checkbox" data-pin '+(pinTemplate?'checked':'')+'> Keep as spell area</label>':''}`}`;toolbar.after(opts);opts.querySelector('[data-shape]').onchange=e=>{if(q.tool==='draw')shape=e.target.value;else measureShape=e.target.value};opts.querySelector('[data-stroke]').onchange=e=>stroke=e.target.value;opts.querySelector('[data-fill]')?.addEventListener('change',e=>fill=e.target.value==='none'?'none':stroke);opts.querySelector('[data-thick]')?.addEventListener('change',e=>thickness=+e.target.value);opts.querySelector('[data-opacity]')?.addEventListener('change',e=>opacity=+e.target.value);opts.querySelector('[data-hidden]')?.addEventListener('change',e=>hiddenDrawing=e.target.checked);opts.querySelector('[data-beam]')?.addEventListener('change',e=>beamWidth=+e.target.value);opts.querySelector('[data-pin]')?.addEventListener('change',e=>pinTemplate=e.target.checked);opts.querySelector('[data-clear-own]')?.addEventListener('click',()=>{if(confirm('Clear your drawings on this scene?'))clearDrawings()});opts.querySelector('[data-clear-all]')?.addEventListener('click',()=>{if(confirm('Clear every drawing on this scene?'))clearDrawings(true)})}
