function shortcuts(){modal('Tabletop shortcuts','<dl class="vtt-shortcut-list"><dt>V / H / M / D / T</dt><dd>Select / Pan / Measure / Draw / token library</dd><dt>Space (hold)</dt><dd>Pan temporarily</dd><dt>Wheel / pinch / + / −</dt><dd>Zoom around the pointer</dd><dt>Alt (drag)</dt><dd>Temporarily bypass snapping</dd><dt>Alt-click / hold</dt><dd>Shared ping</dd><dt>Ctrl+C / V / D</dt><dd>Copy / paste / duplicate tokens</dd><dt>Ctrl+Z / Shift+Z</dt><dd>Undo / Redo</dd><dt>Arrows / Delete / Esc</dt><dd>Nudge / delete / deselect</dd><dt>G / ?</dt><dd>Grid visibility / shortcuts</dd><dt>F</dt><dd>Fog & lighting tools</dd></dl>')}
document.addEventListener('keydown',e=>{const q=state();if(!q?.game||document.querySelector('dialog[open]')||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;const ctrl=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(ctrl&&k==='c'){clipboard=q.scene.tokens.filter(t=>q.selection.has(t.id)).map(C.clone);e.preventDefault()}else if(ctrl&&k==='v'){if(q.dm)edit(()=>{for(const old of clipboard.slice(0,500)){const t=C.clone(old);t.id=crypto.randomUUID();delete t._revision;delete t._restoreRevision;delete t._imageAssetId;t.x+=q.scene.grid;t.y+=q.scene.grid;if(t.meta?.group)t.meta.group='';api().clamp(t);q.scene.tokens.push(t)}});e.preventDefault()}else if(ctrl&&k==='d'){if(q.dm)api().action('duplicate');e.preventDefault()}else if(ctrl&&k==='z'){e.preventDefault();api().undo(!!e.shiftKey)}else if(e.key===' '){space=true;api().space(true);e.preventDefault()}else if(k==='?'){shortcuts();e.preventDefault()}else if(['v','h','m','d'].includes(k)){api().setTool(({v:'select',h:'pan',m:'ruler',d:'draw'})[k]);e.preventDefault()}else if(k==='t'){library();e.preventDefault()}else if(k==='f'){window.ForgeVTTVision?.open()}else if(k==='g'){gridOff=!gridOff;invalidate();e.preventDefault()}else if(e.key==='+'||e.key==='='){api().zoomAt(q.zoom*1.15);e.preventDefault()}else if(e.key==='-'){api().zoomAt(q.zoom/1.15);e.preventDefault()}else if((e.key==='Delete'||e.key==='Backspace')&&selectedDrawing){const id=selectedDrawing;edit(()=>q.scene.drawings=(q.scene.drawings||[]).filter(d=>d.id!==id||!q.dm&&d.ownerId!==window.ForgeCloud?.partyConnection()?.user?.id));selectedDrawing=null;e.preventDefault()}else if(e.key==='Escape'){polygon=[];transient=null;selectedDrawing=null;invalidate()}});
document.addEventListener('keyup',e=>{if(e.key===' '){space=false;api()?.space(false)}});
